local ActivityCakeShopBossRankCell = Class('ActivityCakeShopBossRankCell')

--region lifecycle

function ActivityCakeShopBossRankCell:__init()
    self.bossType = BossRankType.CakeShopBoss
    self.activityContentId = 1
end

function ActivityCakeShopBossRankCell:__delete()
    self.bossType = nil
    self.activityContentId = nil
end

function ActivityCakeShopBossRankCell:Awake()
    ---@type CommonPlayerHeadNode
    self._headNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    ---@type PlayerComponent
    self._playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
end

function ActivityCakeShopBossRankCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
