--region handler
function ActivityCakeShopBossRankCell:OnClickHeadNodeHandler()
    if self.bossType == BossRankType.CakeShopBoss then
        GameUtils.ShowPlayerInfo(self._rankItem.playerId, {
            { id = Constants.UITypeIds.UIActivityMidFestivalBossDialog },
            { id = Constants.UITypeIds.ActivityCakeShopBossMain }
        })
    elseif self.bossType == BossRankType.ParkMiniWorldBoss or self.bossType == BossRankType.ParkMiniWorldBossPartition then
        GameUtils.ShowPlayerInfo(self._rankItem.playerId, {
            { id = Constants.UITypeIds.ParkourBossMain }
        })
    elseif self.bossType == BossRankType.JapaneseStory then
        GameUtils.ShowPlayerInfo(self._rankItem.playerId, {
            { id = Constants.UITypeIds.ActivityJapaneseStoryBossDialog }
        })
    elseif self.bossType == BossRankType.MournBoss then
        GameUtils.ShowPlayerInfo(self._rankItem.playerId, {
            { id = Constants.UITypeIds.MournBossDialog }
        })
    end
end

function ActivityCakeShopBossRankCell:OnClickBtnTeamDetailHandler()
    GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, self._rankItem.team, nil, nil, self._rankItem.name)
end
--endregion handler

--region public
function ActivityCakeShopBossRankCell:Refresh(rankItemInfo, index, bossType, activityContentId)
    self._isEven = index % 2 == 0
    self._rankNo = index
    self._rankItem = rankItemInfo
    self._playerId = self._playerComp:GetPlayerDojo().playerId
    if not isNull(bossType) then
        self.bossType = checkNumber(bossType)
        self.activityContentId = checkNumber(activityContentId)
    end
    self:RefreshUI()
end
--endregion public

--region private
function ActivityCakeShopBossRankCell:RefreshImgRank()
    CfUtils.SetUISwitchImage(self.ImgRank, self._rankNo)
    CfUtils.SetUISwitchImage(self.ImgRank2, self._rankNo)
    CfUtils.SetUISwitchText(self.Txtranking, self._rankNo)
    CfUtils.FillText(self.Txtranking, self._rankNo)
end

function ActivityCakeShopBossRankCell:RefreshPlayerInfo()

    CfUtils.FillText(self.TxtName, self._rankItem.name)
    CfUtils.FillText(self.TextLevel, "Lv." .. checkString(self._rankItem.level))
    CfUtils.FillText(self.TxtDamage, self._rankItem.score)
    CfUtils.SetActive(self.ImgMyself, checkString(self._rankItem.playerId) == self._playerId)
    self._headNodeScr:FreshAvatarFrame(self._rankItem.avatar, self._rankItem.avatarFrame)
    self._headNodeScr:SetCallBack(Bind(self, self.OnClickHeadNodeHandler))
end

function ActivityCakeShopBossRankCell:RefreshRewardsInfo()
    --local voList = self:GetRewardsVos(self.activityContentId)
    local voList = self:GetRewardsVos(1)
    local rewards = {}
    for _, item in ipairs(voList) do
        ---@type MidFestivalBossRankRewardVo
        local vo = item
        if self._rankNo >= vo.upperLimit and self._rankNo <= vo.lowerLimit then
            local rewardsCount = #vo.reward
            for i = 1, rewardsCount do
                table.insert(rewards, {
                    goodsId = vo.reward[i],
                    num = vo.rewardNum[i]
                })
            end
        end
    end
    if table.count(rewards) == 0 then
        CfUtils.SetActive(self.TextNoReward, true)
        CfUtils.SetActive(self.CommonGoodsList , false)
        return
    end

    CfUtils.SetActive(self.TextNoReward, false)
    CfUtils.SetActive(self.CommonGoodsList , true)
    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    scr:FreshBaseUI(rewards)
end

function ActivityCakeShopBossRankCell:GetRewardsVos(type)
    local allVoList = {}
    local function filterData(voList)
        local t = {}
        for i, v in pairs(voList) do
            if checkNumber(v.activityId) == self.activityContentId then
                table.insert(t, v)
            end
        end
        return t
    end
    if self.bossType == BossRankType.CakeShopBoss then
        allVoList = CfUtils.GetCf(AutoIds.IdSetting6249, "ActivityCakeBossRankVo", true)
    elseif self.bossType == BossRankType.ParkMiniWorldBoss then
        allVoList = CfUtils.GetCf(AutoIds.IdSetting6455, "ActivityCakeBossRankVo", true)
        allVoList = filterData(allVoList)
    elseif self.bossType == BossRankType.ParkMiniWorldBossPartition then
        allVoList = CfUtils.GetCf(AutoIds.IdSetting6466, "ActivityCakeBossRankVo", true)
        allVoList = filterData(allVoList)
    elseif self.bossType == BossRankType.JapaneseStory then
        allVoList = CfUtils.GetCf(AutoIds.IdSetting6502, "JapaneseStoryBossRankRewardsVo", true)
    elseif self.bossType == BossRankType.MournBoss then
        allVoList = CfUtils.GetCf(AutoIds.IdSetting6616, "JapaneseStoryBossRankRewardsVo", true)
    end

    local retVoList = {}
    for i, item in ipairs(allVoList) do
        ---@type MidFestivalBossRankRewardVo
        local vo = item
        if vo.type == type then
            table.insert(retVoList, vo)
        end
    end
    table.sort(retVoList, function(a, b)
        return a.id < b.id
    end)
    return retVoList
end

function ActivityCakeShopBossRankCell:RefreshTeamInfo()
    SetButtonAction(self.BtnDetails, Bind(self, self.OnClickBtnTeamDetailHandler))
end

function ActivityCakeShopBossRankCell:RefreshUI()
    CfUtils.SetActive(self.Imgbg1, not self._isEven)
    CfUtils.SetActive(self.Imgbg2, self._isEven)

    self:RefreshImgRank()
    self:RefreshPlayerInfo()
    self:RefreshRewardsInfo()
    self:RefreshTeamInfo()
end
